def find_BIDS_algo_results_dir(
    destination_id: str, output_dir: Union[Path, str]
) -> Path:
    """Isolate BIDS results directory from Flywheel general output.

    Args:
        destination_id (str):
        output_dir (Union[Path, str]):

    Returns:
        The path to the BIDS results-specific directory
    """
    top_level = Path(output_dir).parent
    analysis_dirs = list(top_level.rglob(f"**/*{destination_id}*"))
    if len(analysis_dirs) > 1:
        common_path = commonpath(analysis_dirs)
        return Path(common_path)
    elif not analysis_dirs:
        raise ValueError(f"Did not find a folder matching {destination_id}")
    else:
        return analysis_dirs[0]

def reconcile_existing_and_unzipped_files(target_dir: Path, unzip_dir: Path):
    """Place unzipped files in the proper directory.

    Often archived/zipped inputs are unzipped into /flywheel/v0/work. Depending on the
    intended destination and whether extraneous enclosing folders exist (i.e., destination IDs), this method can be used to simply and consistently relocate files and/or directories to their intended, final resting places.

    Args:
        target_dir (Path): final, resting place for the dir or file
        unzip_dir (Path): initial location of the unzipped archive (often generated by GTK.utils.zip_tools.unzip_archive)
    """
    for file in unzip_dir.rglob("*"):
        if (target_dir / file.name).exists():
            log.info("Found %s but using existing", file.name)
        else:
            if not target_dir.exists():
                target_dir.mkdir(parents=True)
            log.debug("Moving %s to %s", file.name, target_dir / file.name)
            shutil.move(file, target_dir / file.name)

def deprecated(reason: str, version: str):
    """Decorator to mark a function as deprecated and issue a warning message when called.

    This decorator is used to indicate that a function is outdated and will be removed in future versions of the toolkit. It automatically generates a warning message based on the provided reason and version number, informing users of the deprecation and advising them to update their code accordingly.

    When applied to a function, it intercepts calls to that function and emits a DeprecationWarning with the specified reason and version. This helps maintain backward compatibility while guiding users towards newer alternatives.

    Usage:
        @deprecated("New feature replaces this.", "2.0")
        def old_function():
            pass

    Args:
        reason (str): explain why the function is deprecated and suggest an alternative.
        version (str): the version of the toolkit in which the function was deprecated.

    Examples:
        >>> @deprecated("Use new_method instead.", "2.0")
        def old_function():
            print("Old function called.")

        >>> old_function()
        /path/to/module.py:10: DeprecationWarning: old_function is deprecated since version 2.0. Reason: Use new_method instead.
          old_function()
    """

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(
                f"{func.__name__} is deprecated since version {version}. Reason: {reason}",
                category=DeprecationWarning,
                stacklevel=2,
            )
            return func(*args, **kwargs)

        return wrapper

    return decorator

