{
  "id": "bids_anat_file",
  "template": "anat_file",
  "where": {
    "container_type": "file",
    "parent_container_type": "acquisition",
    "file.type": {
      "$in": [
        "nifti",
        "NIfTI"
      ]
    },
    "file.classification.Intent": {
      "$in": [
        "Structural"
      ]
    },
    "file.classification.Measurement": {
      "$in": [
        "T1",
        "T1rho",
        "T2",
        "T2*"
      ]
    }
  },
  "initialize": {
    "Run": {
      "acquisition.label": {
        "$regex": [
          "(^|_)run-(?P<value>\\d+)",
          "(^|_)run-(?P<value>[=+])"
        ]
      },
      "$run_counter": {
        "key": "anat"
      }
    },
    "Suffix": {
      "$switch": {
        "$on": "file.classification.Measurement",
        "$cases": [
          {
            "$eq": [
              "T1"
            ],
            "$value": "T1w"
          },
          {
            "$eq": [
              "T1rho"
            ],
            "$value": "T1rho"
          },
          {
            "$eq": [
              "T2"
            ],
            "$value": "T2w"
          },
          {
            "$eq": [
              "T2*"
            ],
            "$value": "T2star"
          }
        ]
      }
    }
  }
}

